test_input = [
    [3, 6, 2, 0, 8, 3, 1, 1, 1, 3, 6, 2, 0, 8, 3, 1, 1, 1, 3, 6, 2, 0, 8, 3, 1, 1, 1],
    [1, 1, 2, 1, 8, 1, 1, 1, 6, 1, 1, 2, 1, 8, 1, 1, 1, 6, 1, 1, 2, 1, 8, 1, 1, 1, 6],
    [0, 1, 1, 4, 4, 1, 1, 1, 1, 0, 1, 1, 4, 4, 1, 1, 1, 1, 0, 1, 1, 4, 4, 1, 1, 1, 1],
    [1, 1, 1, 1, 1, 2, 1, 1, 8, 1, 1, 1, 1, 1, 2, 1, 1, 8, 1, 1, 1, 1, 1, 2, 1, 1, 8],
    [9, 1, 1, 3, 1, 1, 1, 6, 1, 9, 1, 1, 3, 1, 1, 1, 6, 1, 9, 1, 1, 3, 1, 1, 1, 6, 1]
]

# For each row, find the smallest repeating unit
def find_smallest_period(row):
    for period in range(1, len(row) + 1):
        # Check if row repeats with this period
        matches = True
        for i in range(len(row)):
            if row[i] != row[i % period]:
                matches = False
                break
        if matches:
            return period
    return len(row)

print("Finding smallest repeating units for each row:")
for i, row in enumerate(test_input):
    period = find_smallest_period(row)
    pattern = row[:period]
    print(f"Row {i}: period={period}, pattern={pattern}, pattern repeats {len(row)//period} times")

